void Solver::bump_var(int var, double coeff) {
    if (coeff == 0.0) return;
    const double MAX_ACT = 1e100;
    const double SCALE   = 1e-100;

    double inc = var_inc * coeff;
    double new_act = activity[var] + inc;
    activity[var] = new_act;

    if (new_act > MAX_ACT) {
        // Scale down all activities and the increment to avoid overflow.
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= SCALE;
        }
        var_inc *= SCALE;
    }
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
